import { useMemo, useState, type ChangeEvent } from "react";
import { Link, useNavigate } from "@tanstack/react-router";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";
import { candidates, demoStore, getSelectedCandidate, useDemoStore, type Candidate, type Portal } from "@/lib/mock-store";
import rahulPortrait from "@/assets/rahul-mehta.jpg";
import {
  ArrowUpRight,
  BarChart3,
  Bell,
  BriefcaseBusiness,
  Check,
  ChevronRight,
  CircleDot,
  ClipboardList,
  FileCheck2,
  FileText,
  FolderLock,
  Gauge,
  Inbox,
  LayoutDashboard,
  LockKeyhole,
  LogOut,
  MessageSquare,
  MoreHorizontal,
  PanelLeftClose,
  Plus,
  Send,
  Settings2,
  ShieldCheck,
  Sparkles,
  UserRound,
  Users,
  X,
} from "lucide-react";

type Section = "overview" | "pool" | "requirements" | "campaigns" | "workflow" | "documents" | "profile" | "messages" | "approvals" | "sera" | "audit";

const portalMeta: Record<Portal, { label: string; subtitle: string; sentence: string; name: string }> = {
  candidate: { label: "Candidate", subtitle: "your safe desk", sentence: "Your single safe desk to progress and get placed.", name: "Arjun Kapoor" },
  recruiter: { label: "Recruiter", subtitle: "Priya · Eventrics", sentence: "File requirements and accept from the vetted pool.", name: "Priya Shah" },
  admin: { label: "YZI Admin", subtitle: "the mediator", sentence: "The lock that confirms, shares and audits every sensitive move.", name: "YZI Admin" },
};

const sectionNames: Record<Portal, { id: Section; label: string; icon: typeof LayoutDashboard }[]> = {
  candidate: [
    { id: "overview", label: "Home", icon: LayoutDashboard },
    { id: "workflow", label: "My roles", icon: BriefcaseBusiness },
    { id: "documents", label: "Documents", icon: FileText },
    { id: "profile", label: "Profile", icon: UserRound },
    { id: "messages", label: "Messages", icon: MessageSquare },
  ],
  recruiter: [
    { id: "overview", label: "Overview", icon: LayoutDashboard },
    { id: "requirements", label: "Requirements", icon: ClipboardList },
    { id: "pool", label: "Candidate pool", icon: Users },
    { id: "workflow", label: "Workflow", icon: Gauge },
    { id: "messages", label: "Messages", icon: MessageSquare },
  ],
  admin: [
    { id: "overview", label: "Command center", icon: LayoutDashboard },
    { id: "pool", label: "Candidate pool", icon: Users },
    { id: "campaigns", label: "Campaigns", icon: Sparkles },
    { id: "requirements", label: "Requirements", icon: ClipboardList },
    { id: "approvals", label: "Approvals", icon: FileCheck2 },
    { id: "sera", label: "Sera control", icon: LockKeyhole },
    { id: "audit", label: "Audit log", icon: ShieldCheck },
    { id: "messages", label: "Messages", icon: MessageSquare },
  ],
};

const stages = ["Profile", "Review", "Sent", "Meeting", "Docs", "Interview", "Offer", "Placed"];

export function SeraApp({ initialPortal = "admin" }: { initialPortal?: Portal }) {
  const [portal, setPortal] = useState<Portal>(initialPortal);
  const [section, setSection] = useState<Section>(initialPortal === "admin" ? "overview" : "overview");
  const [showRequirementForm, setShowRequirementForm] = useState(false);
  const [showCampaignForm, setShowCampaignForm] = useState(false);
  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);
  const [toast, setToast] = useState("");
  const navigate = useNavigate();
  const store = useDemoStore();

  const action = (message: string) => {
    setToast(message);
    window.setTimeout(() => setToast(""), 2600);
  };

  const logout = () => {
    setShowLogoutConfirm(false);
    navigate({ to: "/" });
  };

  return (
    <div className={cn("min-h-screen text-foreground antialiased", portal === "candidate" ? "bg-steel-soft/25" : "bg-background")}>
      <div className="flex min-h-screen">
        <aside className={cn("flex w-[248px] shrink-0 flex-col text-rail-text", portal === "candidate" ? "bg-primary" : "bg-rail")}>
          <div className="flex items-center gap-3 px-5 py-5">
            <div className="grid size-9 place-items-center rounded-md bg-rail-soft text-xs font-mono text-sidebar-primary ring-1 ring-sidebar-border">S</div>
            <div className="leading-tight">
              <div className="text-sm font-semibold tracking-tight text-sidebar-primary">SERA</div>
              <div className="font-mono text-[10px] tracking-[0.16em] text-rail-text">YZI · RECRUITMENT OS</div>
            </div>
          </div>

          <div className="px-3">
            <div className={cn("flex items-center gap-3 rounded-md px-3 py-2.5 ring-1", portal === "candidate" ? "bg-sidebar-accent ring-sidebar-border" : "bg-sidebar-accent ring-sidebar-border")}>
              {portal === "candidate" ? <div className="grid size-7 place-items-center rounded-full bg-steel-soft text-[10px] font-semibold text-steel">AK</div> : <div className="grid size-7 place-items-center rounded-md bg-rail-soft text-[10px] font-semibold text-sidebar-primary">{portal === "admin" ? "YZ" : "PS"}</div>}
              <div className="min-w-0"><div className="truncate text-xs font-medium text-sidebar-primary">{portal === "candidate" ? "Arjun Kapoor" : portalMeta[portal].label}</div><div className="font-mono text-[9px] tracking-widest text-rail-text">{portal === "candidate" ? "CAND-0417" : portal === "admin" ? "MEDIATOR" : "EVENTRICS"}</div></div>
            </div>
          </div>

          <nav className="mt-6 space-y-0.5 px-3">
            {sectionNames[portal].map(({ id, label, icon: Icon }) => {
              const active = section === id;
              return (
                <button key={id} type="button" onClick={() => setSection(id)} className={cn("flex w-full items-center gap-3 rounded-md px-3 py-2.5 text-left text-[13px] transition-colors", active ? "bg-sidebar-accent text-sidebar-primary ring-1 ring-sidebar-border" : "text-rail-text hover:bg-sidebar-accent hover:text-sidebar-primary")}>
                  <Icon className="size-4" strokeWidth={1.7} />
                  <span>{label}</span>
                  {label === "Messages" && <span className="ml-auto grid size-4 place-items-center rounded-full bg-signal font-mono text-[9px] text-primary-foreground">2</span>}
                  {label === "Campaigns" && <span className="ml-auto font-mono text-[10px] text-rail-text">3</span>}
                </button>
              );
            })}
          </nav>

          <div className="mt-auto px-3 pb-4">
            <div className="rounded-md bg-rail-soft p-3 ring-1 ring-sidebar-border">
              <div className="flex items-center gap-2 font-mono text-[10px] tracking-widest text-rail-text"><CircleDot className="size-3 text-signal" /> NEXT MOVE</div>
              <div className="mt-2 text-xs leading-relaxed text-sidebar-primary">{portal === "admin" ? "Confirm Neha Joshi · REQ-201" : portal === "recruiter" ? "Review the YZI pool · REQ-104" : store.acceptedRahul ? "Rahul is now in My roles" : "Review your matched role · REQ-104"}</div>
            </div>
          </div>
        </aside>

        <main className="min-w-0 flex-1">
          <header className="sticky top-0 z-20 border-b border-border bg-background/90 backdrop-blur-md">
            <div className="flex items-center gap-4 px-7 py-3.5">
              <div className="min-w-0">
                <div className="truncate text-[15px] font-semibold tracking-tight">{sectionNames[portal].find((item) => item.id === section)?.label}</div>
                <div className="font-mono text-[10px] tracking-[0.08em] text-muted-foreground">{portalMeta[portal].subtitle} · {portalMeta[portal].sentence}</div>
              </div>
              <div className="ml-auto flex items-center gap-2">
                <Link to="/" className="rounded-md border border-border px-2.5 py-1.5 font-mono text-[10px] tracking-widest text-muted-foreground transition-colors hover:bg-muted hover:text-foreground">DEMO MAP</Link>
                <div className="hidden h-6 w-px bg-border sm:block" />
                <span className="hidden font-mono text-[10px] text-muted-foreground sm:block">30 AUG 2026</span>
                <button type="button" aria-label="Notifications" className="grid size-8 place-items-center rounded-md text-muted-foreground hover:bg-muted"><Bell className="size-4" /></button>
                <div className="grid size-8 place-items-center rounded-md bg-steel-soft text-xs font-semibold text-steel">{portal === "admin" ? "YZ" : portal === "recruiter" ? "PS" : "AK"}</div>
                <div className="hidden h-6 w-px bg-border sm:block" />
                <button type="button" onClick={() => setShowLogoutConfirm(true)} className="flex items-center gap-1.5 rounded-md border border-border px-2.5 py-1.5 text-[11px] font-medium text-muted-foreground transition-colors hover:bg-signal-soft hover:text-signal">
                  <LogOut className="size-3.5" /> Log out
                </button>
              </div>
            </div>
          </header>

          <div className="p-5 md:p-7">
            {section === "overview" && <Overview portal={portal} store={store} action={action} onSection={setSection} onRequirement={() => setShowRequirementForm(true)} />}
            {section === "pool" && <Pool portal={portal} store={store} action={action} />}
            {section === "requirements" && <Requirements portal={portal} onNew={() => setShowRequirementForm(true)} action={action} />}
            {section === "campaigns" && <Campaigns onNew={() => setShowCampaignForm(true)} action={action} />}
            {section === "workflow" && <Workflow portal={portal} store={store} action={action} />}
            {section === "documents" && <Documents action={action} />}
            {section === "profile" && <Profile action={action} />}
            {section === "messages" && <Messages store={store} />}
            {section === "approvals" && <Approvals action={action} />}
            {section === "sera" && <SeraControl action={action} />}
            {section === "audit" && <Audit />}
          </div>
        </main>
      </div>

      {showRequirementForm && <RequirementModal onClose={() => setShowRequirementForm(false)} onSave={() => { setShowRequirementForm(false); action("Requirement REQ-318 saved as draft"); }} />}
      {showCampaignForm && <CampaignModal onClose={() => setShowCampaignForm(false)} onSave={() => { setShowCampaignForm(false); action("Campaign CMP-014 saved as draft"); }} />}
      {showLogoutConfirm && (
        <div className="fixed inset-0 z-50 grid place-items-center bg-background/70 p-4 backdrop-blur-sm">
          <div className="sera-rise w-full max-w-sm rounded-lg border border-border bg-card p-6 shadow-2xl">
            <div className="grid size-10 place-items-center rounded-md bg-signal-soft"><LogOut className="size-5 text-signal" /></div>
            <h2 className="mt-4 text-base font-semibold tracking-tight">Log out of {portal === "candidate" ? "your candidate desk" : portal === "recruiter" ? "the recruiter desk" : "the admin command center"}?</h2>
            <p className="mt-2 text-sm leading-relaxed text-muted-foreground">Are you sure? You will return to the demo map and your desk session ends.</p>
            <div className="mt-6 flex justify-end gap-2">
              <Button variant="outline" onClick={() => setShowLogoutConfirm(false)}>No, stay</Button>
              <Button onClick={logout}>Yes, log out</Button>
            </div>
          </div>
        </div>
      )}
      {toast && <div className="fixed bottom-6 right-6 z-50 flex items-center gap-2 rounded-md bg-primary px-4 py-3 text-sm text-primary-foreground shadow-lg"><Check className="size-4 text-ok" />{toast}</div>}
    </div>
  );
}

function PageHeading({ eyebrow, title, description, children }: { eyebrow: string; title: string; description: string; children?: React.ReactNode }) {
  return <div className="mb-6 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><div className="mb-2 font-mono text-[10px] tracking-[0.2em] text-muted-foreground">{eyebrow}</div><h1 className="text-2xl font-semibold tracking-tight md:text-[28px]">{title}</h1><p className="mt-1.5 max-w-2xl text-sm leading-relaxed text-muted-foreground">{description}</p></div>{children}</div>;
}

function Stat({ label, value, note, tone = "neutral" }: { label: string; value: string; note: string; tone?: "neutral" | "ok" | "signal" }) {
  return <div className="sera-rise rounded-lg border border-border bg-card p-4"><div className="font-mono text-[10px] tracking-[0.16em] text-muted-foreground">{label}</div><div className="mt-2 text-2xl font-semibold tracking-tight">{value}</div><div className={cn("mt-1 text-[11px]", tone === "ok" ? "text-ok" : tone === "signal" ? "text-signal" : "text-muted-foreground")}>{note}</div></div>;
}

function Overview({ portal, store, action, onSection, onRequirement }: { portal: Portal; store: ReturnType<typeof useDemoStore>; action: (message: string) => void; onSection: (section: Section) => void; onRequirement: () => void }) {
  if (portal === "candidate") return <CandidateHome store={store} onSection={onSection} />;
  if (portal === "recruiter") return <RecruiterOverview onSection={onSection} onRequirement={onRequirement} />;
  return <AdminOverview store={store} onSection={onSection} action={action} />;
}

function CandidateHome({ store, onSection }: { store: ReturnType<typeof useDemoStore>; onSection: (section: Section) => void }) {
  const current = store.acceptedRahul ? 3 : 2;
  return <div className="space-y-5"><PageHeading eyebrow="CANDIDATE · ARJUN KAPOOR" title="Good morning, Arjun." description="One safe desk for every step. YZI keeps your identity private while your next role moves forward."><span className="flex items-center gap-2 rounded-md bg-ok-soft px-3 py-2 text-xs font-medium text-ok"><span className="size-1.5 rounded-full bg-ok" />Profile active</span></PageHeading><section className="rounded-lg bg-primary p-6 text-primary-foreground"><div className="flex flex-col justify-between gap-5 md:flex-row md:items-start"><div><div className="font-mono text-[10px] tracking-[0.18em] text-sidebar-foreground">YOUR NEXT ACTION</div><h2 className="mt-3 text-xl font-semibold tracking-tight">Review your matched role</h2><p className="mt-2 max-w-md text-sm leading-relaxed text-sidebar-foreground">Eventrics is looking for a Senior .NET engineer in Bengaluru. Your profile is already with YZI for review.</p></div><div className="grid size-10 place-items-center rounded-md bg-sidebar-accent"><ArrowUpRight className="size-5" /></div></div><div className="mt-6 flex flex-wrap items-center gap-3"><Button variant="secondary" onClick={() => onSection("workflow")}>Open My roles <ChevronRight className="size-4" /></Button><span className="font-mono text-[10px] text-sidebar-foreground">REQ-104 · 3.2 YRS · BENGALURU</span></div></section><section className="rounded-lg border border-border bg-card p-5"><div className="flex items-center justify-between"><div><div className="text-sm font-semibold">Your journey</div><div className="mt-1 text-xs text-muted-foreground">YZI unlocks each step as your role progresses.</div></div><span className="font-mono text-[10px] text-muted-foreground">{current} / 8 COMPLETE</span></div><ProgressBar current={current} /><div className="mt-5 grid grid-cols-2 gap-x-4 gap-y-4 text-xs sm:grid-cols-4">{stages.map((stage, index) => <JourneyItem key={stage} label={stage} done={index < current} active={index === current} />)}</div></section><div className="grid gap-5 md:grid-cols-3"><MiniCard icon={FileText} title="Documents" value="2 uploaded" note="1 optional CV missing" onClick={() => onSection("documents")} /><MiniCard icon={UserRound} title="Profile" value="92% complete" note="Work & tags editable" onClick={() => onSection("profile")} /><MiniCard icon={MessageSquare} title="Messages" value="1 unread" note="From YZI Admin" onClick={() => onSection("messages")} /></div></div>;
}

function RecruiterOverview({ onSection, onRequirement }: { onSection: (section: Section) => void; onRequirement: () => void }) {
  return <div className="space-y-5"><PageHeading eyebrow="RECRUITER · PRIYA SHAH · EVENTRICS" title="Your hiring desk." description="Requirements, workflow, and one mediator between you and every candidate."><Button variant="quiet" onClick={onRequirement}><Plus className="size-4" /> File requirement</Button></PageHeading><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Stat label="OPEN REQUIREMENTS" value="2" note="REQ-104 · REQ-201" /><Stat label="POOL MATCHES" value="4" note="Open Candidate pool" tone="ok" /><Stat label="IN WORKFLOW" value="1" note="Ananya · REQ-104" /><Stat label="NEXT MOVE" value="1" note="Proceed reviewed" tone="signal" /></section><section className="grid gap-5 xl:grid-cols-[1.5fr_1fr]"><div className="rounded-lg border border-border bg-card p-5"><SectionTitle title="Active requirement" meta="REQ-104" /><div className="mt-4 rounded-md bg-steel-soft p-4"><div className="font-mono text-[10px] tracking-widest text-steel">REQ-104</div><div className="mt-2 text-base font-semibold">Senior .NET Engineer</div><div className="mt-1 text-xs text-muted-foreground">Bengaluru · 5–8 years · Eventrics</div><div className="mt-4 flex flex-wrap gap-2"><Tag>.NET</Tag><Tag>Azure</Tag><Tag>Microservices</Tag></div></div><div className="mt-4 space-y-3 text-xs"><div className="flex justify-between"><span className="text-muted-foreground">Pool coverage</span><span className="font-medium text-ok">Strong · 8 matched</span></div><div className="h-1.5 overflow-hidden rounded-full bg-muted"><div className="h-full w-[72%] rounded-full bg-ok" /></div><div className="flex justify-between"><span className="text-muted-foreground">Filed</span><span className="font-mono text-[10px]">26 AUG 2026</span></div></div><Button variant="outline" className="mt-5 w-full" onClick={() => onSection("requirements")}>View full requirement <ArrowUpRight className="size-4" /></Button></div><div className="rounded-lg border border-border bg-card p-5"><SectionTitle title="Next in workflow" meta="ANANYA · REQ-104" /><div className="mt-5 flex items-center gap-3"><div className="grid size-11 place-items-center rounded-md bg-steel-soft font-mono text-xs text-steel">AR</div><div><div className="text-sm font-semibold">Ananya Rao</div><div className="mt-1 text-xs text-muted-foreground">.NET · Hyderabad · 4.5 yrs</div></div></div><div className="mt-5"><div className="flex items-center justify-between text-[11px]"><span className="text-muted-foreground">Progress</span><span className="font-mono text-muted-foreground">4 / 8</span></div><ProgressBar current={4} /></div><Button variant="quiet" className="mt-5 w-full" onClick={() => onSection("workflow")}>Open workflow <ChevronRight className="size-4" /></Button></div></section><section className="grid gap-5 md:grid-cols-3"><MiniCard icon={ClipboardList} title="Requirements" value="2 open" note="Latest filed 26 Aug" onClick={() => onSection("requirements")} /><MiniCard icon={Users} title="Candidate pool" value="4 matches" note="Contact protected" onClick={() => onSection("pool")} /><MiniCard icon={MessageSquare} title="YZI Messages" value="2 threads" note="One needs your reply" onClick={() => onSection("messages")} /></section></div>;
}

function AdminOverview({ store, onSection, action }: { store: ReturnType<typeof useDemoStore>; onSection: (section: Section) => void; action: (message: string) => void }) {
  return <div className="space-y-5"><PageHeading eyebrow="YZI ADMIN · COMMAND CENTER" title="The lock on every sensitive click." description="Sera is the engine; YZI is the lock. Recruiters never see a phone, email or address — every spec, doc and identity move is audit-logged here."><div className="flex items-center gap-2 rounded-md bg-signal-soft px-3 py-2 text-xs font-medium text-signal"><span className="size-1.5 rounded-full bg-signal" />2 actions need review</div></PageHeading><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Stat label="ACTIVE POOL" value="148" note="+12 this week" tone="ok" /><Stat label="OPEN REQUIREMENTS" value="7" note="2 pool-thin" /><Stat label="IN WORKFLOW" value={store.acceptedRahul ? "24" : "23"} note="6 meeting · 4 docs" /><Stat label="PLACED · 90D" value="11" note="4 campaigns sourced" tone="ok" /></section><section className="grid gap-5 xl:grid-cols-[1.55fr_1fr]"><CandidatePoolTable portal="admin" store={store} action={action} /><div className="rounded-lg border border-border bg-card p-5"><SectionTitle title="Command queue" meta="2 PENDING" /><div className="mt-4 space-y-3"><QueueItem label="Confirm email" subject="Neha Joshi" meta="REQ-201 · 4m ago" tone="signal" onClick={() => action("Email confirmed for Neha Joshi")} /><QueueItem label="Share docs" subject="Ananya Rao" meta="REQ-104 · 19m ago" tone="steel" onClick={() => action("Document bundle shared with Ananya")} /><QueueItem label="Review identity request" subject="Kiran Nair" meta="Candidate · 1h ago" tone="neutral" onClick={() => onSection("approvals")} /></div><Button variant="outline" className="mt-5 w-full" onClick={() => onSection("approvals")}>Open approvals <ArrowUpRight className="size-4" /></Button></div></section><section className="grid gap-5 lg:grid-cols-3"><DashboardPanel title="Campaigns" meta="3 total" rows={["Java Pune · RUNNING", "Go Bengaluru · DRAFT", "React Delhi · ENDED"]} onClick={() => onSection("campaigns")} /><DashboardPanel title="Requirements" meta="2 pool-thin" rows={["REQ-104 · Eventrics · .NET", "REQ-201 · Eventrics · React"]} onClick={() => onSection("requirements")} /><DashboardPanel title="Audit" meta="READ-ONLY" rows={["Spec sent · Rahul · 09:41", "Docs shared · Ananya · 09:12"]} onClick={() => onSection("audit")} /></section></div>;
}

function CandidatePoolTable({ portal, store, action }: { portal: Portal; store: ReturnType<typeof useDemoStore>; action: (message: string) => void }) {
  return <div className="overflow-hidden rounded-lg border border-border bg-card"><div className="flex items-center justify-between gap-3 border-b border-border px-5 py-4"><div><div className="text-sm font-semibold">Candidate pool</div><div className="mt-1 font-mono text-[10px] tracking-[0.14em] text-muted-foreground">{portal === "admin" ? "FULL IDENTITY · ADMIN ONLY" : "HOUSE POOL · CONTACT HIDDEN"}</div></div><Button variant="outline" size="sm" onClick={() => action("Pool refreshed · 4 matching profiles")}>Refresh <MoreHorizontal className="size-4" /></Button></div><div className="grid grid-cols-[1.55fr_0.8fr_0.65fr_0.9fr] gap-3 border-b border-border px-5 py-2.5 font-mono text-[10px] tracking-widest text-muted-foreground"><span>CANDIDATE</span><span>REQ</span><span>STACK</span><span>ORIGIN</span></div>{candidates.slice(0, 4).map((candidate) => <CandidateRow key={candidate.id} candidate={candidate} selected={candidate.id === store.selectedCandidateId} store={store} portal={portal} action={action} />)}</div>;
}

function CandidateRow({ candidate, selected, store, portal, action }: { candidate: Candidate; selected: boolean; store: ReturnType<typeof useDemoStore>; portal: Portal; action: (message: string) => void }) {
  return <button type="button" onClick={() => demoStore.selectCandidate(candidate.id)} className={cn("grid w-full grid-cols-[1.55fr_0.8fr_0.65fr_0.9fr] items-center gap-3 border-b border-border px-5 py-3 text-left transition-colors last:border-0 hover:bg-muted/60", selected && "bg-steel-soft/70")}>{<div className="flex min-w-0 items-center gap-2.5"><div className={cn("grid size-9 shrink-0 place-items-center rounded-md font-mono text-[10px]", selected ? "bg-steel text-primary-foreground" : "bg-muted text-steel")}>{candidate.initials}</div><div className="min-w-0"><div className="truncate text-[13px] font-medium">{candidate.name}</div><div className="font-mono text-[10px] text-muted-foreground">{candidate.id} · {candidate.years}</div></div></div>}<span className="font-mono text-[11px] font-medium text-steel">{candidate.requirement}</span><span className="text-xs">{candidate.stack}</span><span className="flex min-w-0 items-center gap-1.5 truncate text-[11px] text-muted-foreground"><span className={cn("size-1.5 shrink-0 rounded-full", candidate.origin === "YZI pool" ? "bg-steel" : "bg-signal")} />{candidate.origin}</span>{selected && <CandidateDetail candidate={candidate} portal={portal} store={store} action={action} />}</button>;
}

function CandidateDetail({ candidate, portal, store, action }: { candidate: Candidate; portal: Portal; store: ReturnType<typeof useDemoStore>; action: (message: string) => void }) {
  return <div className="col-span-full mt-1 rounded-md border border-border bg-background p-4" onClick={(event) => event.stopPropagation()}><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-start"><div><div className="flex items-center gap-2"><span className="text-sm font-semibold">{candidate.name}</span><span className="rounded-full bg-ok-soft px-2 py-0.5 text-[10px] font-medium text-ok">{candidate.status === "workflow" ? "In workflow" : "Matched"}</span></div><p className="mt-1 text-xs text-muted-foreground">{candidate.stack} · {candidate.years} · {candidate.city} · {candidate.requirement}</p><p className="mt-3 max-w-lg text-xs leading-relaxed text-muted-foreground">Senior {candidate.stack} engineer matched because of Azure delivery experience, Bengaluru availability, and verified work history.</p></div>{portal === "admin" ? <div className="rounded-md bg-signal-soft px-3 py-2 text-right"><div className="font-mono text-[9px] tracking-widest text-signal">YZI ONLY · CONTACT</div><div className="mt-1 text-[11px] text-signal">{candidate.email}<br />{candidate.phone}</div></div> : <div className="rounded-md bg-muted px-3 py-2 text-right"><div className="font-mono text-[9px] tracking-widest text-muted-foreground">CONTACT</div><div className="mt-1 text-[11px] text-muted-foreground">Hidden from recruiter</div></div>}</div><div className="mt-4 flex flex-wrap items-center justify-between gap-3 border-t border-border pt-3"><div className="flex items-center gap-2 text-[11px] text-muted-foreground"><span className="size-1.5 rounded-full bg-ok" />Why matched: skill + location + experience</div><div className="flex flex-wrap gap-2">{portal === "recruiter" && candidate.id === "CAND-0417" && <Button size="sm" variant={store.acceptedRahul ? "secondary" : "quiet"} onClick={() => { demoStore.acceptRahul(); action("Rahul accepted into workflow · Candidate My roles updated"); }}>{store.acceptedRahul ? <><Check className="size-3.5" />Accepted</> : "Accept into workflow"}</Button>}{portal === "recruiter" && <Button size="sm" variant="outline" onClick={() => action(`${candidate.name} rejected for ${candidate.requirement}`)}>Reject</Button>}{portal === "admin" && <><Button size="sm" variant="quiet" onClick={() => { demoStore.sendSpec(candidate.id); action(`Spec sent · ${candidate.name} · ${candidate.requirement}`); }}><Send className="size-3.5" />{store.sentSpecs.includes(candidate.id) ? "Spec sent" : "Send spec"}</Button><Button size="sm" variant="outline" onClick={() => { demoStore.shareDocs(candidate.id); action(`Docs shared · ${candidate.name}`); }}>Share docs</Button></>}</div></div></div>;
}

function Pool({ portal, store, action }: { portal: Portal; store: ReturnType<typeof useDemoStore>; action: (message: string) => void }) {
  const [lane, setLane] = useState("pool");
  const filtered = useMemo(() => candidates.filter((candidate) => candidate.status === lane), [lane]);
  const lanes = [{ id: "pool", label: "In pool", count: "412" }, { id: "review", label: "Review", count: "68" }, { id: "workflow", label: "Workflow", count: "22" }, { id: "placed", label: "Placed", count: "84" }];
  return <div className="space-y-5"><PageHeading eyebrow={`${portal === "admin" ? "ADMIN" : "RECRUITER"} · POOL`} title="The vetted pool." description={portal === "admin" ? "Full identity is visible here. Every reveal, spec, and document share is logged." : "Select a profile to see the full spec. Contact details stay with YZI."}><div className="rounded-md bg-steel-soft px-3 py-2 font-mono text-[10px] tracking-wide text-steel">POOL FIRST · CAMPAIGN IF THIN</div></PageHeading>{portal === "admin" ? <div className="grid gap-4 md:grid-cols-4">{lanes.map((item) => <div key={item.id} className={cn("border-t-2 p-3", lane === item.id ? "border-signal" : "border-border")}><button type="button" onClick={() => setLane(item.id)} className="flex w-full items-center justify-between text-left"><span className="text-[11px] font-semibold uppercase tracking-wider">{item.label}</span><span className="font-mono text-[10px] text-muted-foreground">{item.count}</span></button><div className="mt-3 space-y-2">{(filtered.length ? filtered : candidates.filter((c) => c.status === item.id)).slice(0, 3).map((candidate) => <button type="button" key={candidate.id} onClick={() => demoStore.selectCandidate(candidate.id)} className={cn("block w-full rounded-md border bg-card p-3 text-left shadow-sm transition-colors hover:border-steel", store.selectedCandidateId === candidate.id && "border-signal") }><div className="text-xs font-semibold">{candidate.name}</div><div className="mt-1 font-mono text-[10px] text-steel">{candidate.requirement} · {candidate.stack}</div></button>)}</div></div>)}</div> : <CandidatePoolTable portal="recruiter" store={store} action={action} />} {portal === "admin" && <SelectedAdminProfile store={store} action={action} />}</div>;
}

function SelectedAdminProfile({ store, action }: { store: ReturnType<typeof useDemoStore>; action: (message: string) => void }) { const candidate = getSelectedCandidate(store.selectedCandidateId); return <div className="rounded-lg border border-border bg-card p-5"><SectionTitle title={`${candidate.name} · full identity`} meta={`${candidate.id} · ${candidate.requirement}`} /><div className="mt-4 grid gap-5 lg:grid-cols-[1fr_1fr_1.2fr]"><div><div className="flex items-center gap-3"><img src={candidate.id === "CAND-0417" ? rahulPortrait : undefined} alt="" width={48} height={48} loading="lazy" className="size-12 rounded-md object-cover" /><div><div className="text-xs text-muted-foreground">Location</div><div className="mt-1 text-sm font-medium">{candidate.city}</div></div></div><div className="mt-4 text-xs text-muted-foreground">Email</div><div className="mt-1 text-sm font-medium">{candidate.email}</div><div className="mt-4 text-xs text-muted-foreground">Phone</div><div className="mt-1 text-sm font-medium">{candidate.phone}</div></div><div><div className="font-mono text-[10px] tracking-widest text-muted-foreground">MILESTONES · {candidate.requirement}</div><ProgressBar current={candidate.id === "CAND-0417" && store.acceptedRahul ? 3 : candidate.status === "workflow" ? 4 : 2} /><div className="mt-3 grid grid-cols-2 gap-y-2 text-[11px]">{stages.map((stage, index) => <JourneyItem key={stage} label={stage} done={index < 2 || (candidate.status === "workflow" && index < 4)} active={index === 2 && candidate.id === "CAND-0417" && !store.acceptedRahul} />)}</div></div><div className="rounded-md bg-signal-soft p-4"><div className="font-mono text-[10px] tracking-widest text-signal">YZI ACTIONS</div><p className="mt-2 text-sm leading-relaxed">Sensitive actions are recorded to the insert-only audit log.</p><div className="mt-4 flex flex-wrap gap-2"><Button size="sm" variant="quiet" onClick={() => { demoStore.sendSpec(candidate.id); action(`Spec sent · ${candidate.requirement}`); }}>Send spec</Button><Button size="sm" variant="outline" onClick={() => { demoStore.shareDocs(candidate.id); action("Documents shared securely"); }}>Share docs</Button></div></div></div></div>; }

function Requirements({ portal, onNew, action }: { portal: Portal; onNew: () => void; action: (message: string) => void }) { const reqs = [{ id: "REQ-104", role: "Senior .NET Engineer", city: "Bengaluru", date: "26 Aug 2026", status: "Pool matched", count: "8 profiles" }, { id: "REQ-201", role: "React Engineer", city: "Pune", date: "24 Aug 2026", status: "Pool thin", count: "2 profiles" }, { id: "REQ-088", role: "Product Designer", city: "Mumbai", date: "21 Aug 2026", status: "In workflow", count: "1 profile" }]; return <div className="space-y-5"><PageHeading eyebrow={`${portal === "admin" ? "YZI ADMIN" : "RECRUITER"} · REQUIREMENTS`} title="Every spec starts with a REQ-ID." description="Recruiters file the need. YZI confirms the match, sends the spec, and keeps contact protected."><Button variant="quiet" onClick={onNew}><Plus className="size-4" /> {portal === "admin" ? "Start in-house brief" : "File requirement"}</Button></PageHeading><div className="overflow-hidden rounded-lg border border-border bg-card"><div className="grid grid-cols-[0.7fr_1.5fr_0.8fr_0.9fr_0.8fr] gap-4 border-b border-border px-5 py-3 font-mono text-[10px] tracking-widest text-muted-foreground"><span>REQ</span><span>ROLE</span><span>CITY</span><span>FILED</span><span>STATUS</span></div>{reqs.map((req) => <button key={req.id} type="button" onClick={() => action(`${req.id} opened · ${req.count}`)} className="grid w-full grid-cols-[0.7fr_1.5fr_0.8fr_0.9fr_0.8fr] gap-4 border-b border-border px-5 py-4 text-left transition-colors last:border-0 hover:bg-muted/60"><span className="font-mono text-xs font-semibold text-steel">{req.id}</span><span><span className="block text-sm font-medium">{req.role}</span><span className="mt-1 block text-[11px] text-muted-foreground">Eventrics · {req.count}</span></span><span className="text-xs text-muted-foreground">{req.city}</span><span className="font-mono text-[10px] text-muted-foreground">{req.date}</span><span className={cn("w-fit rounded-full px-2 py-1 text-[10px] font-medium", req.status === "Pool thin" ? "bg-signal-soft text-signal" : "bg-ok-soft text-ok")}>{req.status}</span></button>)}</div></div>; }

function Campaigns({ onNew, action }: { onNew: () => void; action: (message: string) => void }) { const campaigns = [{ id: "CMP-012", name: "Java Pune", city: "Pune", status: "RUNNING", hits: "42 extracted", dates: "18 Aug — 18 Sep" }, { id: "CMP-014", name: "Go Bengaluru", city: "Bengaluru", status: "DRAFT", hits: "Brief in edit", dates: "—" }, { id: "CMP-009", name: "React Delhi", city: "Delhi", status: "ENDED", hits: "86 extracted", dates: "01 Jul — 31 Jul" }]; return <div className="space-y-5"><PageHeading eyebrow="YZI ADMIN · CAMPAIGNS" title="Campaigns only when the pool is thin." description="Draft the brief, set the guardrails, then let Sera extract matches for YZI to confirm."><Button variant="quiet" onClick={onNew}><Plus className="size-4" /> Start new campaign</Button></PageHeading><div className="grid gap-4 lg:grid-cols-3">{campaigns.map((campaign) => <button type="button" key={campaign.id} onClick={() => action(`${campaign.name} opened · extracted profiles ready`)} className="rounded-lg border border-border bg-card p-5 text-left transition-all hover:-translate-y-0.5 hover:border-steel hover:shadow-md"><div className="flex items-start justify-between"><span className="font-mono text-[10px] tracking-widest text-muted-foreground">{campaign.id}</span><span className={cn("rounded-full px-2 py-1 font-mono text-[9px] tracking-wider", campaign.status === "RUNNING" ? "bg-ok-soft text-ok" : campaign.status === "DRAFT" ? "bg-steel-soft text-steel" : "bg-muted text-muted-foreground")}>{campaign.status}</span></div><div className="mt-5 text-base font-semibold">{campaign.name}</div><div className="mt-1 text-xs text-muted-foreground">{campaign.city} · {campaign.dates}</div><div className="mt-6 flex items-center justify-between border-t border-border pt-3 text-xs"><span className="text-muted-foreground">{campaign.hits}</span><ChevronRight className="size-4 text-muted-foreground" /></div></button>)}</div><div className="rounded-lg border border-border bg-card p-5"><SectionTitle title="Open campaign · extracted profiles" meta="Java Pune · 42" /><div className="mt-4 grid gap-3 md:grid-cols-3"><CampaignHit name="Neha Joshi" match="94% match" status="Confirm email" onClick={() => action("Email confirmed · Neha Joshi")} /><CampaignHit name="Sana Kapoor" match="89% match" status="Review" onClick={() => action("Sana Joshi opened for review")} /><CampaignHit name="Rohan Sethi" match="83% match" status="Reject" onClick={() => action("Rohan Sethi rejected from campaign")} /></div></div></div>; }

function Workflow({ portal, store, action }: { portal: Portal; store: ReturnType<typeof useDemoStore>; action: (message: string) => void }) { const candidate = portal === "candidate" ? { name: "Arjun Kapoor", id: "CAND-0417", req: "REQ-104", stack: ".NET" } : { name: "Ananya Rao", id: "CAND-0501", req: "REQ-104", stack: ".NET" }; const current = portal === "candidate" ? (store.acceptedRahul ? 3 : 2) : 4; return <div className="space-y-5"><PageHeading eyebrow={`${portal === "candidate" ? "CANDIDATE" : "RECRUITER"} · WORKFLOW`} title={portal === "candidate" ? "My roles." : "One candidate, one clear next move."} description={portal === "candidate" ? "Later milestones appear as YZI unlocks them. No recruiter contact details, ever." : "Move Ananya through the workflow. YZI stays between you and the candidate."} /><div className="rounded-lg border border-border bg-card p-5"><div className="flex flex-col justify-between gap-4 border-b border-border pb-5 sm:flex-row sm:items-center"><div className="flex items-center gap-3"><div className="grid size-11 place-items-center rounded-md bg-steel-soft font-mono text-xs text-steel">{candidate.name.split(" ").map((part) => part[0]).join("")}</div><div><div className="text-sm font-semibold">{candidate.name}</div><div className="mt-1 font-mono text-[10px] text-muted-foreground">{candidate.id} · {candidate.req} · {candidate.stack}</div></div></div><span className="rounded-full bg-signal-soft px-2.5 py-1 text-[10px] font-medium text-signal">Milestone {current + 1} / 8</span></div><div className="mt-6 overflow-x-auto pb-2"><div className="flex min-w-[680px] items-start">{stages.map((stage, index) => <div key={stage} className="relative flex flex-1 flex-col items-center text-center"><div className={cn("z-10 grid size-8 place-items-center rounded-full border text-xs font-semibold", index < current ? "border-ok bg-ok text-primary-foreground" : index === current ? "border-signal bg-signal text-primary-foreground" : "border-border bg-background text-muted-foreground")}>{index < current ? <Check className="size-4" /> : index + 1}</div><div className={cn("mt-2 text-[11px]", index <= current ? "font-medium text-foreground" : "text-muted-foreground")}>{stage}</div>{index < stages.length - 1 && <div className={cn("absolute left-1/2 top-4 h-px w-full", index < current ? "bg-ok" : "bg-border")} />}</div>)}</div></div><div className="mt-5 grid gap-4 border-t border-border pt-5 md:grid-cols-3"><div><div className="font-mono text-[10px] tracking-widest text-muted-foreground">CURRENT</div><div className="mt-1 text-sm font-medium">{stages[current]}</div></div><div><div className="font-mono text-[10px] tracking-widest text-muted-foreground">LAST UPDATE</div><div className="mt-1 text-sm font-medium">30 Aug 2026 · YZI Admin</div></div><div className="flex justify-start md:justify-end"><Button variant="quiet" onClick={() => action("Workflow updated · next milestone unlocked")}>{portal === "candidate" ? "Ask YZI" : "Proceed reviewed"} <ChevronRight className="size-4" /></Button></div></div></div></div>; }

function Documents({ action }: { action: (message: string) => void }) { const [files, setFiles] = useState(["Resume · PDF", "Aadhaar · verified"]); const onFile = (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.item(0); if (file) { setFiles((current) => [...current, `${file.name} · pending review`]); action("Document uploaded · awaiting YZI review"); } }; return <div className="space-y-5"><PageHeading eyebrow="CANDIDATE · DOCUMENTS" title="Your document drawer." description="Upload once. YZI reviews and shares only what a recruiter needs for the next milestone."><label className="inline-flex h-9 cursor-pointer items-center justify-center gap-2 rounded-md bg-primary px-4 text-sm font-medium text-primary-foreground shadow-sm transition-colors hover:bg-steel"><Plus className="size-4" /> Upload document<input type="file" className="hidden" onChange={onFile} accept=".pdf,.doc,.docx,.png,.jpg" /></label></PageHeading><div className="grid gap-4 md:grid-cols-2">{files.map((file, index) => <div key={file} className="flex items-center gap-3 rounded-lg border border-border bg-card p-4"><div className={cn("grid size-10 place-items-center rounded-md", index === 1 ? "bg-ok-soft text-ok" : "bg-steel-soft text-steel")}><FileText className="size-5" /></div><div><div className="text-sm font-medium">{file.split(" · ")[0]}</div><div className="mt-1 text-xs text-muted-foreground">{file.split(" · ")[1]}</div></div><Check className="ml-auto size-4 text-ok" /></div>)}<div className="flex min-h-[104px] items-center gap-3 rounded-lg border border-dashed border-border bg-muted/30 p-4"><div className="grid size-10 place-items-center rounded-md bg-background text-muted-foreground"><Plus className="size-5" /></div><div><div className="text-sm font-medium">CV · optional</div><div className="mt-1 text-xs text-muted-foreground">Add a fresher profile if you want YZI to include it.</div></div></div></div></div>; }

function Profile({ action }: { action: (message: string) => void }) { return <div className="space-y-5"><PageHeading eyebrow="CANDIDATE · PROFILE" title="Your profile, in your control." description="Identity is locked by YZI. Work history and expertise stay editable so your matches stay accurate." /><div className="grid gap-5 lg:grid-cols-[0.8fr_1.4fr]"><div className="rounded-lg border border-border bg-card p-5"><div className="flex items-center gap-3"><div className="grid size-16 place-items-center rounded-full bg-steel-soft text-lg font-semibold text-steel">AK</div><div><div className="text-base font-semibold">Arjun Kapoor</div><div className="mt-1 text-xs text-muted-foreground">CAND-0417 · Bengaluru</div></div></div><div className="mt-5 flex items-center justify-between border-t border-border pt-4"><span className="text-xs text-muted-foreground">Profile status</span><span className="rounded-full bg-ok-soft px-2 py-1 text-[10px] font-medium text-ok">Active</span></div><Button variant="outline" className="mt-4 w-full" onClick={() => action("Identity change request started")}>Request identity change</Button><p className="mt-2 text-center text-[10px] leading-relaxed text-muted-foreground">Include a reason. YZI Admin reviews every request.</p></div><div className="rounded-lg border border-border bg-card p-5"><SectionTitle title="Work & expertise" meta="EDITABLE" /><div className="mt-5 grid gap-4 sm:grid-cols-2"><label className="text-xs font-medium">Current city<Input defaultValue="Bengaluru" className="mt-2" /></label><label className="text-xs font-medium">Experience<Input defaultValue="3.2 years" className="mt-2" /></label></div><div className="mt-4"><div className="text-xs font-medium">Expertise chips</div><div className="mt-2 flex flex-wrap gap-2"><Tag>.NET</Tag><Tag>Azure</Tag><Tag>ASP.NET Core</Tag><Tag>Microservices</Tag><button type="button" onClick={() => action("Expertise editor opened")} className="rounded-full border border-dashed border-border px-3 py-1 text-[11px] text-muted-foreground hover:border-steel hover:text-steel"><Plus className="mr-1 inline size-3" /> Add</button></div></div><Button variant="quiet" className="mt-6" onClick={() => action("Profile changes saved")}>Save profile</Button></div></div></div>; }

function Messages({ store }: { store: ReturnType<typeof useDemoStore> }) { return <div className="space-y-5"><PageHeading eyebrow="SECURE INBOX · YZI ONLY" title="Messages." description="No recruiter inbox. No candidate inbox. YZI is the only conversation in the room." /><div className="max-w-3xl overflow-hidden rounded-lg border border-border bg-card"><div className="flex items-center justify-between border-b border-border px-5 py-4"><div className="text-sm font-semibold">YZI Admin</div><span className="rounded-full bg-signal-soft px-2 py-1 font-mono text-[9px] tracking-wider text-signal">1 UNREAD</span></div><div className="divide-y divide-border">{store.messages.map((message) => <div key={`${message.time}-${message.text}`} className={cn("p-5", message.unread && "bg-steel-soft/40")}><div className="flex items-center justify-between"><div className="flex items-center gap-2 text-xs font-medium"><div className="grid size-7 place-items-center rounded-md bg-primary text-[10px] text-primary-foreground">YZ</div>{message.from}</div><span className="font-mono text-[10px] text-muted-foreground">{message.time}</span></div><p className="mt-3 pl-9 text-sm leading-relaxed text-muted-foreground">{message.text}</p></div>)}</div><div className="flex gap-2 border-t border-border p-4"><Input placeholder="Write to YZI Admin…" /><Button variant="quiet" size="icon" aria-label="Send message"><Send className="size-4" /></Button></div></div></div>; }

function Approvals({ action }: { action: (message: string) => void }) { const approvals = [{ title: "Confirm email", subject: "Neha Joshi", meta: "REQ-201 · campaign Java Pune", tone: "signal" }, { title: "Identity request", subject: "Kiran Nair", meta: "Reason: update legal name", tone: "steel" }, { title: "Campaign brief", subject: "Go Bengaluru", meta: "CMP-014 · draft needs edit", tone: "neutral" }]; return <div className="space-y-5"><PageHeading eyebrow="YZI ADMIN · APPROVALS" title="The queue before it moves." description="Confirm, reject, edit, and keep the paper trail intact." /><div className="grid gap-4 lg:grid-cols-3">{approvals.map((item) => <div key={item.title} className="rounded-lg border border-border bg-card p-5"><div className={cn("mb-5 grid size-9 place-items-center rounded-md", item.tone === "signal" ? "bg-signal-soft text-signal" : item.tone === "steel" ? "bg-steel-soft text-steel" : "bg-muted text-muted-foreground")}><FileCheck2 className="size-4" /></div><div className="font-mono text-[10px] tracking-widest text-muted-foreground">{item.title.toUpperCase()}</div><div className="mt-2 text-base font-semibold">{item.subject}</div><div className="mt-1 text-xs text-muted-foreground">{item.meta}</div><div className="mt-5 flex gap-2"><Button size="sm" variant="quiet" onClick={() => action(`${item.title} confirmed · ${item.subject}`)}><Check className="size-3.5" />Confirm</Button><Button size="sm" variant="outline" onClick={() => action(`${item.subject} returned for review`)}>Review</Button></div></div>)}</div></div>; }

function SeraControl({ action }: { action: (message: string) => void }) { return <div className="space-y-5"><PageHeading eyebrow="YZI ADMIN · SERA CONTROL" title="Sera is powerful because YZI is the lock." description="Control the sensitive steps. Unlock only for the action in front of you, then close the door." /><div className="grid gap-5 lg:grid-cols-[1fr_1.4fr]"><div className="rounded-lg bg-primary p-6 text-primary-foreground"><div className="flex items-center gap-3"><div className="grid size-10 place-items-center rounded-md bg-sidebar-accent"><LockKeyhole className="size-5" /></div><div><div className="text-base font-semibold">Sera control</div><div className="mt-1 font-mono text-[10px] tracking-widest text-sidebar-foreground">LOCKED · READY</div></div></div><p className="mt-6 text-sm leading-relaxed text-sidebar-foreground">The engine can match, extract, and prepare. Only YZI can reveal identity, share docs, or confirm a mail.</p><Button variant="secondary" className="mt-6" onClick={() => action("Sera unlocked for one sensitive action")}>Unlock next action <ChevronRight className="size-4" /></Button></div><div className="rounded-lg border border-border bg-card p-5"><SectionTitle title="Sensitive actions" meta="AUDIT-LOGGED" /><div className="mt-4 space-y-3"><ControlRow icon={Send} title="Send spec" desc="Share role scope with recruiter" /><ControlRow icon={FolderLock} title="Share documents" desc="Release only verified files" /><ControlRow icon={ShieldCheck} title="Reveal identity" desc="Admin-only contact access" /></div></div></div></div>; }

function Audit() { const events = [["09:41", "Spec sent", "Rahul Mehta · REQ-104", "signal"], ["09:12", "Docs shared", "Ananya Rao · REQ-104", "steel"], ["08:54", "Pool matched", "Neha Joshi · REQ-201", "ok"], ["Yesterday", "Sera unlock", "Documents · one action", "neutral"], ["Yesterday", "Requirement filed", "REQ-201 · Eventrics", "steel"]]; return <div className="space-y-5"><PageHeading eyebrow="YZI ADMIN · INSERT-ONLY" title="Audit log." description="A read-only record of every sensitive click. No edits. No deletions." /><div className="max-w-4xl overflow-hidden rounded-lg border border-border bg-card"><div className="grid grid-cols-[0.6fr_1fr_1.6fr_0.5fr] gap-4 border-b border-border px-5 py-3 font-mono text-[10px] tracking-widest text-muted-foreground"><span>TIME</span><span>ACTION</span><span>SUBJECT</span><span>ACTOR</span></div>{events.map(([time, action, subject, tone]) => <div key={`${time}-${action}`} className="grid grid-cols-[0.6fr_1fr_1.6fr_0.5fr] gap-4 border-b border-border px-5 py-4 text-xs last:border-0"><span className="font-mono text-[10px] text-muted-foreground">{time}</span><span className="flex items-center gap-2 font-medium"><span className={cn("size-1.5 rounded-full", tone === "signal" ? "bg-signal" : tone === "steel" ? "bg-steel" : tone === "ok" ? "bg-ok" : "bg-muted-foreground")} />{action}</span><span className="text-muted-foreground">{subject}</span><span className="font-mono text-[10px] text-muted-foreground">YZI</span></div>)}</div></div>; }

function SectionTitle({ title, meta }: { title: string; meta: string }) { return <div className="flex items-center justify-between gap-3"><div className="text-sm font-semibold tracking-tight">{title}</div><span className="font-mono text-[10px] tracking-wider text-muted-foreground">{meta}</span></div>; }
function ProgressBar({ current }: { current: number }) { return <div className="mt-4 flex items-center gap-1">{stages.map((stage, index) => <div key={stage} className={cn("h-1.5 flex-1 rounded-full", index < current ? "bg-ok" : index === current ? "bg-signal" : "bg-muted")} />)}</div>; }
function JourneyItem({ label, done, active }: { label: string; done?: boolean; active?: boolean }) { return <div className={cn("flex items-center gap-2", !done && !active && "text-muted-foreground")}><span className={cn("grid size-4 place-items-center rounded-full border", done ? "border-ok bg-ok text-primary-foreground" : active ? "border-signal bg-signal" : "border-border")}>{done && <Check className="size-2.5" />}</span><span>{label}</span></div>; }
function Tag({ children }: { children: React.ReactNode }) { return <span className="rounded-full bg-steel-soft px-2.5 py-1 text-[11px] font-medium text-steel">{children}</span>; }
function MiniCard({ icon: Icon, title, value, note, onClick }: { icon: typeof FileText; title: string; value: string; note: string; onClick: () => void }) { return <button type="button" onClick={onClick} className="rounded-lg border border-border bg-card p-4 text-left transition-colors hover:border-steel hover:bg-steel-soft/30"><div className="flex items-center justify-between"><div className="grid size-8 place-items-center rounded-md bg-muted text-steel"><Icon className="size-4" /></div><ArrowUpRight className="size-4 text-muted-foreground" /></div><div className="mt-4 text-sm font-semibold">{title}</div><div className="mt-1 text-lg font-semibold tracking-tight">{value}</div><div className="mt-1 text-xs text-muted-foreground">{note}</div></button>; }
function QueueItem({ label, subject, meta, tone, onClick }: { label: string; subject: string; meta: string; tone: "signal" | "steel" | "neutral"; onClick: () => void }) { return <button type="button" onClick={onClick} className="flex w-full items-center gap-3 rounded-md border border-border p-3 text-left transition-colors hover:bg-muted"><span className={cn("size-2 rounded-full", tone === "signal" ? "bg-signal" : tone === "steel" ? "bg-steel" : "bg-muted-foreground")} /><span className="min-w-0 flex-1"><span className="block text-xs font-medium">{label} · {subject}</span><span className="mt-1 block truncate font-mono text-[10px] text-muted-foreground">{meta}</span></span><ChevronRight className="size-4 text-muted-foreground" /></button>; }
function DashboardPanel({ title, meta, rows, onClick }: { title: string; meta: string; rows: string[]; onClick: () => void }) { return <button type="button" onClick={onClick} className="rounded-lg border border-border bg-card p-4 text-left transition-colors hover:border-steel"><SectionTitle title={title} meta={meta} /><div className="mt-4 space-y-3">{rows.map((row) => <div key={row} className="flex items-center gap-2 text-xs"><span className="size-1.5 rounded-full bg-steel" />{row}</div>)}</div></button>; }
function CampaignHit({ name, match, status, onClick }: { name: string; match: string; status: string; onClick: () => void }) { return <button type="button" onClick={onClick} className="rounded-md border border-border p-3 text-left hover:border-steel"><div className="flex items-center justify-between gap-2"><span className="text-xs font-medium">{name}</span><span className="font-mono text-[10px] text-ok">{match}</span></div><div className="mt-3 flex items-center justify-between text-[10px] text-muted-foreground"><span>Java · Pune</span><span className="rounded bg-signal-soft px-1.5 py-1 text-signal">{status}</span></div></button>; }
function ControlRow({ icon: Icon, title, desc }: { icon: typeof Send; title: string; desc: string }) { return <div className="flex items-center gap-3 rounded-md border border-border p-3"><div className="grid size-8 place-items-center rounded-md bg-steel-soft text-steel"><Icon className="size-4" /></div><div><div className="text-xs font-medium">{title}</div><div className="mt-1 text-[11px] text-muted-foreground">{desc}</div></div><PanelLeftClose className="ml-auto size-4 rotate-180 text-muted-foreground" /></div>; }

function RequirementModal({ onClose, onSave }: { onClose: () => void; onSave: () => void }) { return <ModalShell eyebrow="NEW REQUIREMENT" title="File a requirement" onClose={onClose}><div className="grid gap-4 sm:grid-cols-2"><label className="text-xs font-medium">Role<Input className="mt-2" defaultValue="Senior .NET Engineer" /></label><label className="text-xs font-medium">Target city<Input className="mt-2" defaultValue="Bengaluru" /></label><label className="text-xs font-medium">Experience<Input className="mt-2" defaultValue="5–8 years" /></label><label className="text-xs font-medium">CTC band<Input className="mt-2" defaultValue="₹24–32 LPA" /></label></div><label className="mt-4 block text-xs font-medium">Must-have skills<Textarea className="mt-2" defaultValue=".NET, Azure, Microservices" /></label><div className="mt-5 flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancel</Button><Button variant="quiet" onClick={onSave}>Save REQ-318</Button></div></ModalShell>; }
function CampaignModal({ onClose, onSave }: { onClose: () => void; onSave: () => void }) { return <ModalShell eyebrow="CAMPAIGN BRIEF · DRAFT" title="Start a new campaign" onClose={onClose}><div className="grid gap-4 sm:grid-cols-2"><label className="text-xs font-medium">Role<Input className="mt-2" defaultValue="Go Backend Engineer" /></label><label className="text-xs font-medium">Target city<Input className="mt-2" defaultValue="Bengaluru" /></label><label className="text-xs font-medium">Age range<Input className="mt-2" defaultValue="24–38" /></label><label className="text-xs font-medium">Experience<Input className="mt-2" defaultValue="3–7 years" /></label><label className="text-xs font-medium">CTC range<Input className="mt-2" defaultValue="₹18–28 LPA" /></label><label className="text-xs font-medium">Start date<Input className="mt-2" defaultValue="05 Sep 2026" /></label></div><div className="mt-4 rounded-md bg-steel-soft p-3 text-xs text-steel"><div className="font-mono text-[10px] tracking-widest">GUARDRAILS</div><div className="mt-2 flex flex-wrap gap-2"><Tag>Verified email</Tag><Tag>Verified phone</Tag><Tag>Exclude house pool</Tag></div></div><div className="mt-5 flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancel</Button><Button variant="quiet" onClick={onSave}>Save draft</Button></div></ModalShell>; }
function ModalShell({ eyebrow, title, onClose, children }: { eyebrow: string; title: string; onClose: () => void; children: React.ReactNode }) { return <div className="fixed inset-0 z-40 grid place-items-center bg-primary/25 p-4 backdrop-blur-sm"><div className="max-h-[90vh] w-full max-w-xl overflow-y-auto rounded-lg border border-border bg-background p-6 shadow-2xl"><div className="flex items-start justify-between gap-4"><div><div className="font-mono text-[10px] tracking-widest text-muted-foreground">{eyebrow}</div><div className="mt-2 text-xl font-semibold tracking-tight">{title}</div></div><button type="button" onClick={onClose} aria-label="Close dialog" className="grid size-8 place-items-center rounded-md text-muted-foreground hover:bg-muted"><X className="size-4" /></button></div><div className="mt-6">{children}</div></div></div>; }
